luded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mohd-misbahul-munir-masduki','idris-ahmad','syed-abu-hussin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0019: concurrent ownership or identity change'; end if; end $$;

